{"title":"What regressed","type":"vega","aggs":[],"params":{"spec":"{
    "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
    "title": "What regressed",
    "data": {
        "url": {
            "index": "app-logs-*",
            "body": {
                "size": 0,
                "aggs": {
                    "shapes": {
                        "terms": {
                            "field": "os.hash",
                            "size": 50
                        },
                        "aggs": {
                            "before": {
                                "filter": {
                                    "range": {
                                        "@timestamp": {
                                            "%timefilter%": true,
                                            "shift": -1,
                                            "unit": "hour"
                                        }
                                    }
                                },
                                "aggs": {
                                    "p95": {
                                        "percentiles": {
                                            "field": "took",
                                            "percents": [
                                                95
                                            ]
                                        }
                                    }
                                }
                            },
                            "after": {
                                "filter": {
                                    "range": {
                                        "@timestamp": {
                                            "%timefilter%": true
                                        }
                                    }
                                },
                                "aggs": {
                                    "p95": {
                                        "percentiles": {
                                            "field": "took",
                                            "percents": [
                                                95
                                            ]
                                        }
                                    }
                                }
                            },
                            "established": {
                                "bucket_selector": {
                                    "buckets_path": {
                                        "b": "before>_count"
                                    },
                                    "script": "params.b > 0"
                                }
                            },
                            "slowdown": {
                                "bucket_script": {
                                    "buckets_path": {
                                        "b": "before>p95[95.0]",
                                        "a": "after>p95[95.0]"
                                    },
                                    "script": "params.b == 0 ? 0 : params.a / params.b"
                                }
                            },
                            "worst": {
                                "bucket_sort": {
                                    "sort": [
                                        {
                                            "slowdown": {
                                                "order": "desc"
                                            }
                                        }
                                    ],
                                    "size": 3
                                }
                            },
                            "shape": {
                                "terms": {
                                    "field": "os.sig",
                                    "size": 1
                                }
                            }
                        }
                    }
                },
                "query": {
                    "bool": {
                        "must": [
                            "%dashboard_context-must_clause%"
                        ],
                        "filter": [
                            "%dashboard_context-filter_clause%",
                            {
                                "bool": {
                                    "should": [
                                        {
                                            "range": {
                                                "@timestamp": {
                                                    "%timefilter%": true,
                                                    "shift": -1,
                                                    "unit": "hour"
                                                }
                                            }
                                        },
                                        {
                                            "range": {
                                                "@timestamp": {
                                                    "%timefilter%": true
                                                }
                                            }
                                        }
                                    ],
                                    "minimum_should_match": 1
                                }
                            }
                        ],
                        "must_not": [
                            "%dashboard_context-must_not_clause%"
                        ]
                    }
                }
            }
        },
        "format": {
            "property": "aggregations.shapes.buckets"
        }
    },
    "transform": [
        {
            "calculate": "datum.slowdown.value",
            "as": "value"
        },
        {
            "calculate": "datum.shape && datum.shape.buckets && datum.shape.buckets.length ? datum.shape.buckets[0].key : ''",
            "as": "signature"
        },
        {
            "calculate": "datum.doc_count + '  ·  ' + (datum.shape && datum.shape.buckets && datum.shape.buckets.length ? datum.shape.buckets[0].key : '')",
            "as": "label"
        }
    ],
    "mark": {
        "type": "bar",
        "tooltip": true
    },
    "encoding": {
        "y": {
            "field": "key",
            "type": "nominal",
            "title": "shape",
            "axis": {
                "labelLimit": 200
            },
            "sort": {
                "field": "value",
                "order": "descending"
            }
        },
        "tooltip": [
            {
                "field": "key",
                "type": "nominal",
                "title": "hash"
            },
            {
                "field": "signature",
                "type": "nominal",
                "title": "signature"
            },
            {
                "field": "value",
                "type": "quantitative",
                "title": "× vs the hour before"
            },
            {
                "field": "doc_count",
                "type": "quantitative",
                "title": "records"
            }
        ],
        "x": {
            "field": "value",
            "type": "quantitative",
            "title": "× vs the hour before",
            "stack": null
        }
    }
}"}}

